package io.github.psd2live.i18n

import platform.Foundation.NSLocale
import platform.Foundation.preferredLanguages

/**
 * The iPad's translations: the desktop's Messages*.properties, embedded at build time (EmbeddedMessages, generated by
 * the rigger's build), looked up as ResourceBundle does - the language's bundle, then the base (English) one.
 */
object IpadTranslations {
	private val bundles = HashMap<String, Map<String, String>>()

	private fun bundle(tag: String): Map<String, String> = bundles.getOrPut(tag) {
		parseProperties(EmbeddedMessages.text(tag) ?: return@getOrPut emptyMap())
	}

	/** The language tag in use; the device's first preferred language the bundles have, else English. */
	var languageTag: String = (NSLocale.preferredLanguages.firstOrNull() as? String).orEmpty()
		.replace('_', '-').substringBefore('-').lowercase().takeIf { it in EmbeddedMessages.tags } ?: "en"

	fun text(key: String, arguments: Array<out Any?>): String {
		val pattern = bundle(languageTag)[key] ?: bundle("en")[key] ?: return "!$key!"
		return platformKeyWords(if (arguments.isEmpty()) pattern else formatMessage(pattern, arguments))
	}
}

actual fun tr(key: String, vararg arguments: Any?): String = IpadTranslations.text(key, arguments)

actual fun currentLanguageTag(): String = IpadTranslations.languageTag

internal actual val usesMacKeyWords: Boolean = true
